// Suchgebiete und Kategorien. Hier Städte ergänzen: Name, Breite, Länge, Radius in km.
const staedte = [
  { ort: 'Mannheim', lat: 49.4875, lon: 8.4660, radius_km: 15 },
  { ort: 'Frankfurt am Main', lat: 50.1109, lon: 8.6821, radius_km: 15 },
];
// OpenStreetMap-Kategorien für Hundebetriebe
const kategorien = [
  { kategorie: 'Hundesalon', tag: 'shop=pet_grooming' },
  { kategorie: 'Zoofachgeschäft', tag: 'shop=pet' },
  { kategorie: 'Hundepension / -tagesstätte', tag: 'amenity=animal_boarding' },
  { kategorie: 'Hundeschule / -training', tag: 'amenity=animal_training' },
];
const items = [];
for (const s of staedte) {
  for (const k of kategorien) {
    const [key, value] = k.tag.split('=');
    const r = Math.round(s.radius_km * 1000);
    const query = `[out:json][timeout:60];(node["${key}"="${value}"](around:${r},${s.lat},${s.lon});way["${key}"="${value}"](around:${r},${s.lat},${s.lon}););out center tags;`;
    items.push({ json: { ort_suche: s.ort, kategorie: k.kategorie, tag: k.tag, query } });
  }
}
return items;

// Wandelt die OpenStreetMap-Antworten in Tabellenzeilen um. Nur Daten, die in OSM stehen.
const heute = new Date().toISOString().slice(0, 10);
const gesehen = new Set();
const zeilen = [];
const anfragen = $('Suchgebiete & Kategorien').all();
$input.all().forEach((item, i) => {
  const meta = (anfragen[i] && anfragen[i].json) || {};
  const elemente = Array.isArray(item.json.elements) ? item.json.elements : [];
  for (const el of elemente) {
    const t = el.tags || {};
    if (!t.name) continue; // ohne Namen nicht verwertbar
    const osm_id = `${el.type}/${el.id}`;
    if (gesehen.has(osm_id)) continue;
    gesehen.add(osm_id);
    const strasse = [t['addr:street'], t['addr:housenumber']].filter(Boolean).join(' ');
    zeilen.push({ json: {
      osm_id,
      name: t.name,
      kategorie: meta.kategorie || '',
      strasse,
      plz: t['addr:postcode'] || '',
      ort: t['addr:city'] || meta.ort_suche || '',
      website: t.website || t['contact:website'] || '',
      telefon: t.phone || t['contact:phone'] || '',
      email_oeffentlich: t.email || t['contact:email'] || '',
      quelle: 'OpenStreetMap (© OpenStreetMap-Mitwirkende, ODbL)',
      zuletzt_gesehen: heute,
    } });
  }
});
return zeilen;

// Nur Zeilen ohne Bewertung; höchstens 20 pro Lauf (Kostenkontrolle).
const MAX_PRO_LAUF = 20;
return $input.all()
  .filter(i => i.json.osm_id && !String(i.json.bewertung || '').trim())
  .slice(0, MAX_PRO_LAUF);

// Liest die Claude-Antwort (JSON) und bereitet das Tabellen-Update vor.
const heute = new Date().toISOString().slice(0, 10);
const quellen = $('Noch nicht bewertete auswählen').all();
return $input.all().map((item, i) => {
  const osm_id = quellen[i] ? quellen[i].json.osm_id : '';
  let text = '';
  try { text = item.json.content[0].text; } catch (e) { text = ''; }
  let d = {};
  try { d = JSON.parse(text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1)); } catch (e) { d = {}; }
  const passt = ['ja', 'nein', 'unklar'].includes(d.passt) ? d.passt : 'unklar';
  return { json: {
    osm_id,
    bewertung: passt,
    begruendung: d.begruendung || 'Antwort nicht auswertbar – bitte manuell prüfen.',
    telefonleitfaden: d.telefonleitfaden || '',
    bewertet_am: heute,
    status: 'bewertet',
  } };
});

const alle = $('Bewertung auswerten').all();
const n = (w) => alle.filter(i => i.json.bewertung === w).length;
return [{ json: { text:
  `Knuddelwuff Lead-Suche: ${alle.length} Betriebe bewertet.\n` +
  `passt: ${n('ja')} · passt nicht: ${n('nein')} · unklar: ${n('unklar')}\n` +
  `Details und Telefon-Leitfäden stehen in der Pipeline-Tabelle. Es wurde nichts versendet.` } }];
